  function alertValue(rule) { const dataset = data(); if (!dataset) return { value: NaN, detail: "No data" }; const rows = dataset.rows, values = rows.map(row => numberValue(row[rule.field])).filter(value => value !== null); if (rule.operator === "missing") return { value: rows.length ? (rows.length - rows.filter(row => row[rule.field] !== "" && row[rule.field] != null).length) / rows.length * 100 : 0, detail: "missing rate" }; if (rule.operator === "change") { const mid = Math.floor(values.length / 2), before = values.slice(0, mid), after = values.slice(mid), a = before.reduce((x, y) => x + y, 0) / Math.max(1, before.length), b = after.reduce((x, y) => x + y, 0) / Math.max(1, after.length); return { value: a ? Math.abs((b - a) / a * 100) : 0, detail: "half-to-half change" }; } return { value: values.length ? values.reduce((a, b) => a + b, 0) / values.length : NaN, detail: "average" }; }
  function addAlert() { const name = $("#alert-name").value.trim(), field = $("#alert-field").value, threshold = Number($("#alert-value").value); if (!name || !field || !Number.isFinite(threshold)) return studio.toast("Add an alert name, field, and threshold."); addRecord("alertRules", { id: uid("alert"), name, field, operator: $("#alert-operator").value, threshold, active: true, lastTriggeredAt: null }, "Threshold alert created"); $("#alert-name").value = ""; }
  function evaluateAlerts() { let fired = 0; project().alertRules.filter(rule => rule.active).forEach(rule => { const result = alertValue(rule), hit = rule.operator === "lt" ? result.value < rule.threshold : result.value > rule.threshold; if (hit && (!rule.lastTriggeredAt || now() - rule.lastTriggeredAt > 60000)) { rule.lastTriggeredAt = now(); notify(rule.name, `${rule.field} ${result.detail} is ${format(result.value)}; threshold ${format(rule.threshold)}.`, "alert"); fired++; } }); audit("Alert rules evaluated", "Monitoring", `${fired} triggered`); studio.markDirty(); renderAll(); studio.toast(fired ? `${fired} alert${fired === 1 ? "" : "s"} triggered.` : "All thresholds are within range."); }
