  function bytesToBase64(bytes) { let binary = ""; bytes.forEach(byte => binary += String.fromCharCode(byte)); return btoa(binary); }
  async function createSecureShare() { const title = $("#share-title").value.trim() || `${project().name} read-only report`, pass = $("#share-passphrase").value; if (pass.length < 8) return studio.toast("Use a passphrase of at least eight characters."); if (!crypto.subtle) return studio.toast("Browser encryption is unavailable."); const salt = crypto.getRandomValues(new Uint8Array(16)), iv = crypto.getRandomValues(new Uint8Array(12)), material = await crypto.subtle.importKey("raw", new TextEncoder().encode(pass), "PBKDF2", false, ["deriveKey"]), key = await crypto.subtle.deriveKey({ name: "PBKDF2", salt, iterations: 150000, hash: "SHA-256" }, material, { name: "AES-GCM", length: 256 }, false, ["encrypt"]), cipher = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(JSON.stringify(sharePayload(title))))), bundle = { salt: bytesToBase64(salt), iv: bytesToBase64(iv), cipher: bytesToBase64(cipher) };
    const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${esc(title)}</title><style>body{margin:0;background:#f4f7fb;color:#172033;font:15px/1.6 Arial}main{max-width:850px;margin:8vh auto;padding:25px}section{padding:32px;background:white;border-radius:20px;box-shadow:0 18px 50px #00133c18}input,button{padding:12px;border-radius:9px;border:1px solid #dbe4ef}button{background:#0062f1;color:white;font-weight:bold}h1{color:#00133c;font-family:Georgia}article{margin-top:20px;padding-top:15px;border-top:1px solid #e5e7eb}</style></head><body><main><section id="lock"><h1>Protected Signal Noir report</h1><p>Enter the passphrase shared by the report owner.</p><input id="p" type="password"><button id="o">Open report</button><p id="e"></p></section><section id="r" hidden></section></main><script>const B=${JSON.stringify(bundle)};const b=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));o.onclick=async()=>{try{const m=await crypto.subtle.importKey('raw',new TextEncoder().encode(p.value),'PBKDF2',false,['deriveKey']);const k=await crypto.subtle.deriveKey({name:'PBKDF2',salt:b(B.salt),iterations:150000,hash:'SHA-256'},m,{name:'AES-GCM',length:256},false,['decrypt']);const d=JSON.parse(new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:b(B.iv)},k,b(B.cipher))));lock.hidden=true;r.hidden=false;const add=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;r.appendChild(n)};add('h1',d.title);add('p',d.goal||'Read-only project report');(d.metrics||[]).forEach(x=>{const a=document.createElement('article');const h=document.createElement('h3');h.textContent=x.name;const q=document.createElement('p');q.textContent=x.formula;a.append(h,q);r.appendChild(a)});(d.story?.beats||[]).forEach(x=>{add('h2',x.title);add('p',x.text)});add('small','Generated '+new Date(d.generatedAt).toLocaleString())}catch(x){e.textContent='Incorrect passphrase or damaged file.'}}<\/script></body></html>`;
    download(`${slug(title)}-secure.html`, html, "text/html"); audit("Encrypted share created", "Share", title); studio.markDirty(); studio.toast("Encrypted read-only share downloaded."); }
