    $("#request-form").onsubmit = submitRequest; $("#create-form-btn").onclick = createForm; $("#add-delivery-btn").onclick = addDelivery; $("#add-knowledge-btn").onclick = addKnowledge; $("#knowledge-search").oninput = renderKnowledge;
    $("#run-agent-council-btn").onclick = runAgentCouncil; $("#start-meeting-btn").onclick = startMeeting; $("#add-portal-asset-btn").onclick = addPortalAsset; $("#export-portal-btn").onclick = exportPortal; $$('[data-market-filter]').forEach(button => button.onclick = () => { marketFilter = button.dataset.marketFilter; $$('[data-market-filter]').forEach(node => node.classList.toggle("active", node === button)); renderMarket(); });
    voiceSetup(); $("#voice-start-btn").onclick = () => recognition?.start(); $("#voice-read-btn").onclick = readBriefing; window.DataHubCollaboration?.subscribe(handleRemote); window.addEventListener("datahub:project-render", renderAll); setInterval(() => { if (activeMeetingId) renderMeeting(); }, 1000); renderAll(); setTimeout(processDueDeliveries, 200);
